import{_ as l,o as t,c as a,a2 as s}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Supermarket","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/supermarket.md","filePath":"zh/guides/supermarket.md","lastUpdated":1781675678000}'),i={name:"zh/guides/supermarket.md"};function r(o,e,n,p,d,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="supermarket" tabindex="-1">Supermarket <a class="header-anchor" href="#supermarket" aria-label="Permalink to &quot;Supermarket&quot;">​</a></h1><p>Supermarket 是 Memoh 内置的 <strong>插件</strong> 和 <strong>Skills</strong> 目录。在 v0.13 中，插件是把 MCP 资源、Skills、Hooks、认证要求和安装脚本一起打包安装的推荐方式。</p><p>Web UI 会在 Settings 下显示 Supermarket，并提供两个 tab：</p><ul><li><strong>Plugins</strong></li><li><strong>Skills</strong></li></ul><hr><h2 id="安装插件" tabindex="-1">安装插件 <a class="header-anchor" href="#安装插件" aria-label="Permalink to &quot;安装插件&quot;">​</a></h2><ol><li>在 Web UI 中打开 <strong>Supermarket</strong>。</li><li>切到 <strong>Plugins</strong> tab。</li><li>选择一个插件并点击 <strong>Install</strong>，或进入插件详情页点击 <strong>Install to Bot</strong>。</li><li>选择目标 Bot。</li><li>填写插件 manifest 要求的变量。</li><li>确认安装。</li><li>如果插件返回 <code>needs_auth</code>，完成 OAuth 弹窗授权。</li><li>Memoh 会打开目标 Bot 的 <strong>Plugins</strong> tab。</li></ol><p>安装过程中，Memoh 会获取插件 manifest，在存在可信 Supermarket bundle 时下载并解压插件资产，执行 manifest 的 <code>install</code> 命令，并创建 Bot 级插件安装记录。</p><p>插件详情页会展示插件的 MCP 资源、打包 Skills、认证类型、作者、版本、Schema 版本和链接。</p><hr><h2 id="安装-skill" tabindex="-1">安装 Skill <a class="header-anchor" href="#安装-skill" aria-label="Permalink to &quot;安装 Skill&quot;">​</a></h2><ol><li>在 Web UI 中打开 <strong>Supermarket</strong>。</li><li>切到 <strong>Skills</strong> tab。</li><li>选择一个 Skill 并点击 <strong>Install</strong>，或进入 Skill 详情页点击 <strong>Install to Bot</strong>。</li><li>选择目标 Bot。</li><li>确认安装。</li><li>Skill 会出现在该 Bot 的 <strong>Skills</strong> tab 中。</li></ol><p>独立 Skill 会安装到 Bot 的 managed skills 目录。插件提供的 Skills 则通过插件 bundle 安装。</p><hr><h2 id="配置-supermarket" tabindex="-1">配置 Supermarket <a class="header-anchor" href="#配置-supermarket" aria-label="Permalink to &quot;配置 Supermarket&quot;">​</a></h2><p>默认情况下，Memoh 会从这里读取 Supermarket 内容：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">supermarket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://supermarket.memoh.ai&quot;</span></span></code></pre></div><p>运维方可以把 <code>supermarket.base_url</code> 指向其它可信目录。该 endpoint 会用于插件 manifest、插件 bundle 下载、Skill 列表、Skill 详情和 Skill 下载。</p><hr><h2 id="插件-bundle-内容" tabindex="-1">插件 Bundle 内容 <a class="header-anchor" href="#插件-bundle-内容" aria-label="Permalink to &quot;插件 Bundle 内容&quot;">​</a></h2><p>可信插件 bundle 可以提供：</p><ul><li><code>skills/</code>：作为插件提供的 Skills 被发现。</li><li><code>hooks.json</code>：只会从已启用且状态为 <code>ready</code> 的插件安装中加载。</li><li><code>scripts/</code>：供 manifest 的 <code>install</code> 命令使用的辅助脚本。</li></ul><p>Bundle 文件会解压到目标 Bot 工作区内的 <code>/data/.memoh/plugins/&lt;plugin_id&gt;</code>。归档路径检查会忽略不支持的条目，并拒绝不安全路径。</p><hr><h2 id="贡献" tabindex="-1">贡献 <a class="header-anchor" href="#贡献" aria-label="Permalink to &quot;贡献&quot;">​</a></h2><p>新插件或 Skills 可提交到：</p><ul><li><a href="https://github.com/memohai/supermarket" target="_blank" rel="noreferrer">memohai/supermarket</a></li></ul>`,27)])])}const m=l(i,[["render",r]]);export{k as __pageData,m as default};
